def source_cloze(ch,n,answer):
    # The manually authored template has been compared with the rendered page.
    if n==1:template=CLOZE[ch][0]
    else:
        qs=json.loads((ASSETS/f'content/chapter{ch}.json').read_text())
        template=next(q for q in qs if q['sourceNumber']==n and q['section']!='چهارگزینه‌ای')['steps'][0]['clozeTemplate']
    Q(ch,n,[C(re.sub(r'^[۰-۹0-9]+-\s*','',template))],answer)

