def write():
    """Apply layouts first, then practice; safe to run repeatedly."""
    source={r['id']:r for r in json.loads((ROOT/'qa/source/all-chapters-index.json').read_text())}
    all_q=[]
    from native_scientific_figures import OriginalFigures
    originals=OriginalFigures(preserve_existing=True)
    for ch in range(11,16):
        path=ASSETS/f'content/chapter{ch}.json'
        questions=json.loads(path.read_text())
        for q in questions:
            cid=q['canonicalId'];record=json.loads(json.dumps(DATA[cid]))
            if q['section']=='چهارگزینه‌ای':
                stem,options,key=MCQ[ch][q['sourceNumber']-1]
                assert source[cid]['keyLetter']==key,cid
                q['steps'][0]['options']=[dict(text=letter+'- '+value,correct=letter==key)for letter,value in zip(['الف','ب','ج','د'],options)]
            q['nativeQuestion']=record['question'];q['nativeAnswer']=record['answer']
            for asset in FIGURES.get(cid,[]):q['nativeQuestion'].insert(1,F(asset))
            if cid in {'g7_ch14_q04','g7_ch15_q06'}:
                spec=(55,23.1,64.3)if cid=='g7_ch14_q04'else(58,42.0,108.02)
                next(b for b in q['nativeQuestion']if b['type']=='figure')['asset']=originals.extract(cid,spec)
            q['nativeEdition']='1405-visual-transcription-v3'
            for s in q['steps']:
                if s['kind']in ['match','classify']:s['allowTokenReuse']=True
            all_q.append(q)
        path.write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n')
    review_practice(all_q)
    for ch in range(11,16):
        (ASSETS/f'content/chapter{ch}.json').write_text(json.dumps([q for q in all_q if q['relatedChapter']==ch],ensure_ascii=False,indent=2)+'\n')
    assert len(all_q)==85 and len(DATA)==85
    originals.finish()

def review_practice(questions):
    by_id={q['canonicalId']:q for q in questions}
    def question(ch,n):return by_id[f'g7_ch{ch:02}_q{n:02}']
    def row(ch,n,index,choices,left=None,equivalent=True):
        s=question(ch,n)['steps'][0];pair=s['pairs'][index];old=pair['right']
        pair['right']=choices[0];pair['choices']=choices
        if left is not None:pair['left']=left
        if old!=choices[0] and equivalent:s.setdefault('choiceAliases',{})[old]=choices[0]
        if s.get('choices') and choices[0]not in s['choices']:
            s['choices']=[choices[0]if c==old else c for c in s['choices']]
    def note(ch,n,text):
        q=question(ch,n);q['practiceUsesPrintedKey']=False;q['sourceReviewNote']=text
    row(11,1,3,['پریاخته ای ساده','تک یاخته ای','پریاخته ای با اندام های تخصص یافته'])
    # The image contains both red and white blood cells. Mature human red cells
    # have no nucleus: retain the printed key and explain the practice criterion.
    row(11,3,3,['غشا و میان‌یاخته مشترک‌اند؛ گلبول قرمز بالغ انسان هسته ندارد.','همهٔ یاخته‌های خونی انسان، حتی گلبول قرمز بالغ، هسته دارند.','هیچ‌یک از این یاخته‌ها غشای یاخته ندارد.'],equivalent=False)
    note(11,3,'در شکل، یاخته‌های خونی نیز آمده‌اند. عبارت «همگی هسته دارند» در کلید برای گلبول قرمز بالغ انسان درست نیست. معیار تمرین، اشتراک غشا و میان‌یاخته با توجه به این استثناست؛ متن کلید چاپی حفظ شده است.')
    row(11,4,3,['عبور انتخابی مواد؛ غشا ورود و خروج مواد را متناسب با ویژگی آن‌ها تنظیم می‌کند.','عبور آزاد و یکسان همهٔ مواد از غشا، بدون هیچ محدودیت','جلوگیری کامل از ورود آب و مواد مورد نیاز به یاخته'])
    row(11,8,1,['آبی متیل برای افزایش وضوح بخش‌هایی مانند هستهٔ یاخته','افزودن ماسه برای بیشتر شدن بزرگ‌نمایی میکروسکوپ','آب خالص برای حذف هسته و مشاهدهٔ آن'])
    question(12,1)['sourceReviewNote']='تقسیم ویتامین‌ها به محلول در آب و چربی درست است؛ اما عبارت «در بدن ذخیره نمی‌شوند» دربارهٔ همهٔ ویتامین‌های محلول در آب دقیق نیست. ویتامین B۱۲ استثنای مهمی است و در بدن ذخیره می‌شود. جای خالی‌های این تمرین به همان گروه‌بندی مربوط‌اند.'
    row(12,3,0,['تأمین انرژی برای فعالیت‌های بدن','تنظیم ورود و خروج مواد از یاخته به جای غشا','جایگزینی کامل آب و مواد معدنی بدن'])
    row(12,4,0,['مقدار یکسان لوگول روی تکه‌های سیب‌زمینی و نان و خیار پوست‌کنده، در شرایط یکسان','گرم کردن ظرف‌های خالی بدون تماس معرف با نمونه‌ها','افزودن آب به نمونه‌ها و مقایسهٔ رنگ خود ظرف‌ها'])
    row(12,4,1,['پدید آمدن رنگ آبی تیره در نمونهٔ دارای نشاسته','فقط خیس شدن نمونه، بدون تغییر رنگ معرف','افزایش جرم ظرف بدون بررسی رنگ نمونه'])
    row(12,4,2,['سیب‌زمینی و نان آبی تیره می‌شوند؛ خیار در این آزمایش این تغییر رنگ را ندارد.','خیار آبی تیره می‌شود؛ نان و سیب‌زمینی هیچ تغییری نمی‌کنند.','هر سه فقط بر اساس رنگ ظرف آبی می‌شوند.'])
    question(12,4)['sourceReviewNote']='در متن سؤال، نان نیز آمده اما در توضیح چاپی پاسخ از قلم افتاده است. تمرین هر سه نمونهٔ خواسته‌شده را بررسی می‌کند؛ متن اصلی پاسخنامه حفظ شده است.'
    row(12,6,0,['مالیدن مغز گردو و آب سبزی روی دو بخش کاغذ و مقایسه پس از خشک شدن آب','مقایسهٔ کاغذ گردوی خشک با کاغذ خیس، پیش از تبخیر آب','مقایسهٔ رنگ ظرف‌ها بدون تماس نمونه با کاغذ'])
    row(12,6,1,['باقی ماندن لکهٔ نیمه‌شفاف گردو پس از خشک شدن، در برابر نماندن چنین لکه‌ای از آب سبزی','شفاف شدن موقتی هر کاغذ خیس، به‌تنهایی نشانهٔ چربی است.','تنها تیره بودن رنگ سبزی، وجود چربی را ثابت می‌کند.'])
    row(12,8,0,['مصرف بیش از نیازِ چربی و انرژی می‌تواند خطر چاقی و بیماری قلبی‌عروقی را افزایش دهد.','مصرف هر مقدار چربی همیشه از بیماری قلبی جلوگیری می‌کند.','بدن هیچ نیازی به چربی ندارد و باید همهٔ چربی‌ها حذف شوند.'])
    row(12,8,1,['بسیاری از چربی‌های جامد، چربی اشباع بیشتری دارند و مصرف زیادشان خطر قلبی‌عروقی را بالا می‌برد.','چربی جامد پس از خوردن، به همان شکل جامد وارد رگ و گیر می‌کند.','هر روغن مایع را می‌توان بدون محدودیت مصرف کرد.'],equivalent=False)
    note(12,8,'چربی خورده‌شده به همان حالت جامد در رگ رسوب نمی‌کند. ترکیب اسیدهای چرب و مقدار مصرف بر چربی خون و خطر قلبی‌عروقی اثر می‌گذارد. تمرین این رابطه را دقیق‌تر بیان می‌کند؛ کلید اصلی تغییر نکرده است.')
    row(12,10,0,['رژیم گیاهیِ نامتنوع ممکن است پروتئین یا مواد مغذی کافی نرساند؛ گیاهخواریِ متنوع و برنامه‌ریزی‌شده الزاماً کمبود پروتئین ایجاد نمی‌کند.','هر فرد گیاهخوار حتماً دچار کمبود پروتئین می‌شود، حتی با رژیم متنوع و کافی.','هیچ غذای گیاهی پروتئین یا آمینو اسید ندارد.'],left='احتمال مشکل و شرط ایجاد آن',equivalent=False)
    note(12,10,'گیاهخواری به‌تنهایی دلیل قطعی کمبود پروتئین نیست. تنوع و کفایت منابع پروتئین و سایر مواد مغذی اهمیت دارد. معیار تمرین، احتمال کمبود در رژیم نامتناسب است؛ تعمیم پاسخ چاپی بدون تغییر و جداگانه حفظ شده است.')
    row(12,14,0,['نور خورشید به ساخت ویتامین D در پوست کمک می‌کند؛ این ویتامین جذب کلسیم از روده و سلامت استخوان را پشتیبانی می‌کند.','نور خورشید بدون نیاز به ویتامین یا غذا، مستقیماً استخوان را می‌سازد.','نور خورشید کلسیم را در پوست تولید می‌کند.'])
